export STAGE=/project/community/jjyeung/okh7/813f42db/c20d400 STEP=400 WALLTIME=04:00:00
#!/bin/bash
# Run on Orchard login. STEP=200, 400 or 544; override SOURCE_1TGZ/SOURCE_SHA256 only together.
set -euo pipefail
umask 077
: "${STAGE:=/project/community/jjyeung/okh7/813f42db/d}"
: "${STEP:=200}"
: "${WALLTIME:=04:00:00}"
: "${SOURCE_1TGZ:=/project/community/jjyeung/okh7/a15_cot_ap4e8c539166092f0c/1.tgz}"
: "${SOURCE_SHA256:=c3187ab9f88b3eb5a7ab1e30a8010e4ef86acb49d6c76e98fd97eec393b4e45a}"
case "$STEP" in 200|400|544) ;; *) echo 'STEP must be 200, 400 or 544' >&2; exit 1;; esac
test ! -e "$STAGE"
mkdir -m 700 "$STAGE"
/usr/bin/python3 -B - "$STAGE" "$STEP" <<'PYASSETS'
import base64,gzip,hashlib,json,sys
from pathlib import Path
stage=Path(sys.argv[1]);step=sys.argv[2]
assets = {'b.py': {'sha256': 'ef1cdea1c417fb56dc3d8ee947c4682263e05724f54155c8c8a12b8a759a0e82', 'data': ''}, 'build_support.py': {'sha256': 'e9134b1a6bc20e36dea3afe23a7d5852bc32c24a97a8d44e513b8dbe75d08f7e', 'data': ''}, 'make_items_d.py': {'sha256': 'd262861cbddd05a093425c26138ff89217f86a3bde68e5875e5bfb7ee463184b', 'data': ''}, 'bind_D200.json': {'sha256': 'c3db3512872198a301809ef99022cf12085e4583003e6c6557d85721b40a5542', 'data': ''}, 'bind_D544.json': {'sha256': '0ecfda4c85e29fc630d61204d59c76b3451bb55f6c108f54876a2f65cc85d239', 'data': ''}, 'bind_D400.json': {'sha256': '26a03aab99af0effc355810a027933f4036763635bddcc7d542e78efd68dc22d', 'data': ''}, 'TIMING_D.json': {'sha256': '8fd16b19f7558b93a29c8f5cd63f0440bb6e4886306ef7378ea2c95db0cdf74b', 'data': ''}, 'place_fill_d.py': {'sha256': 'ecffed9165c355bfc8a384fdefd93d24691395e94467b726708dfca749c0e09e', 'data': ''}, 'dryres_d.py': {'sha256': 'e1981c7909b96006a9df9adaf2397c4a70210f7263f58ba484aff81923c225f2', 'data': ''}, 'score_d.py': {'sha256': '1c83087115ad9c565b7810a546d719bd6782a7946dd755f0c7168394deba8276', 'data': ''}, 'items/dist580.json': {'sha256': 'ff9795a886be8173f67ca3bba9bc5271fde5c6f35a58855478e29965b93063bb', 'data': ''}}
for name,spec in assets.items():
    raw=gzip.decompress(base64.b64decode(spec['data']))
    assert hashlib.sha256(raw).hexdigest()==spec['sha256']
    path=stage/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)
(stage/'binding.json').write_bytes((stage/('bind_D'+step+'.json')).read_bytes())
PYASSETS
/usr/bin/python3 -B "$STAGE/b.py" "$STAGE" "$SOURCE_1TGZ" "$SOURCE_SHA256" "$STAGE/items/dist580.json" "$STAGE/binding.json" --time "$WALLTIME"
/usr/bin/python3 -B - "$STAGE" <<'PYRESULT'
import json,sys
from pathlib import Path
r=json.loads((Path(sys.argv[1])/'BUILD.json').read_text())['D']
print('token='+r['token'])
print('delivery_dir='+r['delivery_dir'])
print('sha256='+r['delivery_sha256'])
print('walltime='+r['walltime']+' budget_fits='+str(r['budget_fits']))
PYRESULT
